module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

typedef enum logic [2:0] {
    WALK_LEFT  = 3'b000,
    WALK_RIGHT = 3'b001,
    FALL_LEFT  = 3'b010,
    FALL_RIGHT = 3'b011,
    DIG_LEFT   = 3'b100,
    DIG_RIGHT  = 3'b101
} state_t;

state_t state, next_state;

always_ff @(posedge clk or posedge areset) begin
    if (areset)
        state <= WALK_LEFT;
    else
        state <= next_state;
end

always_comb begin
    next_state = state;
    case (state)
        WALK_LEFT: begin
            if (!ground)
                next_state = FALL_LEFT;
            else if (dig)
                next_state = DIG_LEFT;
            else if (bump_left)
                next_state = WALK_RIGHT;
        end
        WALK_RIGHT: begin
            if (!ground)
                next_state = FALL_RIGHT;
            else if (dig)
                next_state = DIG_RIGHT;
            else if (bump_right)
                next_state = WALK_LEFT;
        end
        FALL_LEFT: begin
            if (ground)
                next_state = WALK_LEFT;
        end
        FALL_RIGHT: begin
            if (ground)
                next_state = WALK_RIGHT;
        end
        DIG_LEFT: begin
            if (!ground)
                next_state = FALL_LEFT;
        end
        DIG_RIGHT: begin
            if (!ground)
                next_state = FALL_RIGHT;
        end
        default: next_state = WALK_LEFT;
    endcase
end

always_comb begin
    walk_left = 0;
    walk_right = 0;
    aaah = 0;
    digging = 0;
    case (state)
        WALK_LEFT:  walk_left = 1;
        WALK_RIGHT: walk_right = 1;
        FALL_LEFT:  begin aaah = 1; end
        FALL_RIGHT: begin aaah = 1; end
        DIG_LEFT:   digging = 1;
        DIG_RIGHT:  digging = 1;
        default:    walk_left = 1;
    endcase
end

endmodule

